-- RLS: leitura pública (vitrine), escrita pública para demo.
-- ATENÇÃO: com a chave anon qualquer visitante com a chave consegue escrever.
-- Para produção, crie um usuário no Auth e troque as políticas de escrita para
--   using (auth.role() = 'authenticated')  -- confira supabase/README.md

alter table public.store_state enable row level security;

drop policy if exists "store_state select" on public.store_state;
create policy "store_state select"
  on public.store_state for select
  using (true);

drop policy if exists "store_state insert" on public.store_state;
create policy "store_state insert"
  on public.store_state for insert
  with check (true);

drop policy if exists "store_state update" on public.store_state;
create policy "store_state update"
  on public.store_state for update
  using (true)
  with check (true);
